const value = (input, fallback = '') => typeof input === 'string' ? input : fallback;
const redact = (input) => value(input, 'Workflow execution failed.')
  .replace(/Bearer\s+[^\s,;]+/gi, 'Bearer [REDACTED]')
  .replace(/(token|secret|authorization|cookie)=?[^\s,;]+/gi, '$1=[REDACTED]')
  .replace(/https?:\/\/[^\s]+/gi, '[URL REDACTED]')
  .slice(0, 500);

const execution = $json.execution ?? {};
const trigger = $json.trigger ?? {};
const workflow = $json.workflow ?? {};
const error = execution.error ?? trigger.error ?? {};
const cause = error.cause ?? {};

return {
  json: {
    alert: 'n8n order-to-HubSpot workflow failed',
    workflowId: value(workflow.id, 'unknown'),
    workflowName: value(workflow.name, 'unknown'),
    executionId: value(execution.id, 'not-saved'),
    lastNode: value(execution.lastNodeExecuted, value(error.node?.name, 'unknown')),
    mode: value(execution.mode, value(trigger.mode, 'unknown')),
    errorMessage: redact(value(error.message, value(cause.message)))
  }
};
